function shopCondition(s){const out=[];for(const [k,v]of Object.entries(s))if(k!=='itemId')out.push(({needFloor:'需求樓層',needChapter:'需求章節',after:'前置條件',qty:'數量',price:'價格',requires:'前置條件'}[k]||k)+' '+(typeof v==='object'?JSON.stringify(v):v));return out.join(' · ')||'一般上架';}
function skillsPage(params){main.innerHTML=intro('武器技能','比較八種流派的基礎攻擊、增益與技能分支。')+`<div class="v2-filters">${field('流派',select('s-style',option('','所有流派')+Object.entries(styles).map(([k,v])=>option(k,v)).join('')))}${field('熟練等級',select('s-level',Array.from({length:10},(_,i)=>option(i+1,'Lv'+(i+1))).join('')))}${field('搜尋','<input id="s-q" type="search" placeholder="技能或分支名稱">')}</div><div id="s-results"></div>`;
 const selected=D.buffs.concat(D.skills).find(x=>x.id===params.get('id')&&(!params.get('style')||x.style===params.get('style')));if(selected)$('s-style').value=selected.style;
 filters(()=>{const style=$('s-style').value,level=+$('s-level').value,q=$('s-q').value;const list=D.skills.filter(x=>(!style||x.style===style)&&(!q||(named(x)+' '+text(x.desc)+' '+D.skillPaths.filter(p=>p.skill===x.id).map(p=>text(p.name)).join(' ')).includes(q)));$('s-results').innerHTML=note('倍率為每段的技能參考倍率；總段數、冷卻與目標數依所選熟練等級計算。武器、天賦分支、抗性、增益和敵方防禦會再改變實際傷害。')+`<div class="v2-skillgrid">${list.map(x=>{const s=G.skillStats(x,level);return`<article class="panel v2-skill" id="skill-${esc(x.id)}"><div class="v2-actions">${tag(styles[x.style])}${tag('角色 Lv'+x.reqLevel)}</div><h2>${esc(named(x))}</h2><p>${esc(text(x.desc))}</p><dl class="v2-stats">${[['段數',s.hits],['每段倍率','×'+nf(s.multiplier)],['目標上限',s.targets],['冷卻',nf(s.cooldownMs/1000)+' 秒']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${skillEffects(x)}<details><summary>兩條技能分支</summary>${D.skillPaths.filter(p=>p.skill===x.id).map(p=>`<div class="v2-branch"><h3>${esc(text(p.name))}</h3><p>${esc(text(p.desc))}</p></div>`).join('')}</details></article>`;}).join('')||empty()}</div><div class="section-title"><h2>增益技能</h2></div>${table(['技能','需求','對象','效果','持續／冷卻'],D.buffs.filter(x=>(!style||x.style===style)&&(!q||(named(x)+' '+text(x.desc)).includes(q))).map(x=>`<tr><td>${esc(named(x))}<small class="v2-sub">${styles[x.style]}</small></td><td>Lv${x.reqLevel}</td><td>${x.party?'隊伍':'自身'}</td><td>${Object.entries(x.effect).map(([k,v])=>esc(statName(k))+' '+(v>0?'+':'')+pct(v)).join(' · ')}</td><td>${nf(x.ms/1000)} 秒／${nf(x.cooldownMs/1000)} 秒</td></tr>`).join(''))}`;});}
function skillEffects(x){const out=[];for(const [k,label]of Object.entries({bleed:'持續傷害',armorBreak:'破防',weaken:'削弱',guard:'減傷'})){if(x[k])out.push(label+' '+pct(x[k].pct)+' · '+nf(x[k].ms/1000)+' 秒');}if(x.critBonus)out.push('額外暴擊率 +'+pct(x.critBonus));if(x.needShield)out.push('需要盾牌');if(x.taunt)out.push('嘲諷');if(x.heal)out.push('包含回復效果');return out.length?'<p class="v2-effect">'+out.map(esc).join(' · ')+'</p>':'';}
function nodeLabel(n){if(n.skill){if(n.kind==='branch')return text(n.branch.name);return named(D.skills.find(s=>s.id===n.skill)||{id:n.skill});}if(n.kind==='perk')return named(D.talents.find(x=>'pk:'+x.id===n.id)||{id:n.id});if(n.kind==='buff')return named(D.buffs.find(x=>x.id===n.buff)||{id:n.id});if(n.kind==='slot')return'額外技能欄位';return statName(n.stat||n.id);}
function nodeDesc(n){if(n.kind==='branch')return text(n.branch.desc);const p=D.talents.find(x=>'pk:'+x.id===n.id);if(p)return text(p.desc);if(n.stat&&D.statSteps[n.stat])return'每點 +'+val(n.stat,D.statSteps[n.stat]);return({skill:'技能等級與常駐流派效果',buff:'提升增益與常駐流派效果',slot:'增加可配置技能數量'}[n.kind]||'依天賦節點效果生效');}
function talentsPage(){main.innerHTML=intro('天賦與技能分支','等級每提高一級獲得一點基本天賦點；各流派分開規劃。')+`<div class="v2-filters">${field('流派',select('t-style',Object.entries(styles).map(([k,v])=>option(k,v)).join('')))}</div><div id="t-results"></div>`;filters(()=>{const style=$('t-style').value,nodes=D.talentNodes.filter(n=>n.style===style);$('t-results').innerHTML=note('技能、增益、分支、特色天賦和常駐能力都在同一棵天賦樹。投點需要符合階層門檻與連接條件，可在'+a('build',null,'配裝模擬器')+'試配。')+`<div class="v2-cards">${D.talents.filter(x=>x.style===style).map(x=>`<article class="panel"><span class="eyebrow">第 ${x.tier+1} 階 · 上限 ${x.max} 點</span><h2>${esc(named(x))}</h2><p>${esc(text(x.desc))}</p></article>`).join('')}</div>${Array.from({length:8},(_,tier)=>{const list=nodes.filter(n=>n.tier===tier);return list.length?`<details class="panel" ${tier===0?'open':''}><summary>第 ${tier+1} 階 · 前置投入 ${D.talentCosts[tier]} 點</summary>${table(['節點','類型','上限','效果'],list.map(n=>`<tr><td>${esc(nodeLabel(n))}</td><td>${esc({skill:'技能',branch:'技能分支',perk:'特色天賦',passive:'常駐能力',buff:'增益',slot:'技能欄位'}[n.kind]||n.kind)}</td><td>${n.max}</td><td>${esc(nodeDesc(n))}</td></tr>`).join(''))}</details>`:'';}).join('')}`;});}
function questsPage(params,materialsOnly=false){const id=params.get('id'),c=D.chapters.find(x=>x.id===id),q=D.sideQuests.find(x=>x.id===id);if(c){main.innerHTML=intro(esc(titleChapter(c)),`所在樓層 ${c.floor} · 需求樓層 ${c.needFloor||c.floor}`)+`<div class="v2-actions"><a class="button secondary" href="#quests">← 任務列表</a></div><section class="panel"><h2>任務流程</h2><ol class="v2-queststeps">${(c.steps||[]).map(s=>`<li><p>${goalText(s.goal)}</p>${known(text(s.text))?'<p>'+esc(text(s.text))+'</p>':''}${known(text(s.hint))?'<p class="subtle">'+esc(text(s.hint))+'</p>':''}<small>${rewardText(s.reward)}</small></li>`).join('')}</ol><h3>章節獎勵</h3><p>${rewardText(c.reward)}</p></section>`;return;}if(q){main.innerHTML=intro(esc(known(text(q.title))?text(q.title):q.id),`第 ${q.floor} 層 · 支線任務`)+`<a class="button secondary" href="#quests">← 任務列表</a><section class="panel"><p>${known(text(q.desc))?esc(text(q.desc)):''}</p><p>${q.type==='kill'?'擊倒 '+a('monsters',q.target,mobName(q.target))+' ×'+nf(q.qty||1):esc(q.type||'依任務條件')}</p>${q.needChapter?'<p>需求章節 '+a('quests',q.needChapter,titleChapter(D.chapters.find(x=>x.id===q.needChapter)||{id:q.needChapter,floor:q.floor}))+'</p>':''}<p>獎勵：${rewardText(q.reward)}</p></section>`;return;}
 if(materialsOnly){const list=D.chapters.flatMap(c=>(c.steps||[]).filter(s=>s.goal?.kind==='collect').map(s=>({c,s})));main.innerHTML=intro('任務素材','從章節收集目標查找素材與對應怪物。')+note('收集目標和指定怪物已列出；未確認的掉落機率保留為待確認。')+table(['素材','數量','指定怪物','章節'],list.map(({c,s})=>`<tr><td>${a('equipment',s.goal.itemId,itemName(s.goal.itemId))}</td><td>${nf(s.goal.qty||1)}</td><td>${s.goal.from?a('monsters',s.goal.from,mobName(s.goal.from)):'依劇情條件'}</td><td>${a('quests',c.id,titleChapter(c))}</td></tr>`).join(''));return;}
 main.innerHTML=intro('商店與任務','依樓層查找章節、支線與商店。')+`<div class="v2-filters">${field('樓層',select('q-floor',floorOptions()))}${field('內容',select('q-type',option('chapters','章節流程')+option('side','支線任務')+option('shops','城鎮商店')))}${field('搜尋','<input id="q-q" type="search" placeholder="任務、目標或區域名稱">')}</div><div id="q-results"></div>`;filters(()=>{const f=$('q-floor').value,q=$('q-q').value.toLowerCase(),type=$('q-type').value;let list=type==='chapters'?D.chapters:type==='side'?D.sideQuests:D.areas.filter(x=>x.shop?.length);list=list.filter(x=>(!f||x.floor===+f)&&(!q||(JSON.stringify(x)).toLowerCase().includes(q)));pageList($('q-results'),list,rows=>type==='shops'?table(['樓層／商店','商品數','商品範例'],rows.map(x=>`<tr><td>${a('floors',x.id,`第 ${x.floor} 層 ${named(x)}`)}</td><td>${x.shop.length}</td><td>${x.shop.slice(0,5).map(s=>a('equipment',s.itemId,itemName(s.itemId))).join('、')}</td></tr>`).join('')):table(['任務','樓層','條件／目標','獎勵'],rows.map(x=>`<tr><td>${a('quests',x.id,type==='chapters'?titleChapter(x):known(text(x.title))?text(x.title):x.id)}</td><td>${x.floor}</td><td>${type==='chapters'?(x.steps||[]).length+' 個步驟 · 需求樓層 '+(x.needFloor||x.floor):x.type==='kill'?a('monsters',x.target,mobName(x.target))+' ×'+nf(x.qty||1):esc(x.type||'劇情')}</td><td>${rewardText(x.reward)}</td></tr>`).join('')));});}
function uniquePage(){main.innerHTML=intro('獨特技能','八種流派都有對應獨特技能與取得流程。')+note('舊版獨特技能倍率已撤下。新版部分效果在連線後才會提供，未確認前不顯示舊數值。')+`<div class="v2-cards">${Object.entries(D.uniqueNames).map(([style,name])=>{const q=D.uniqueQuests[style];return`<article class="panel"><span class="eyebrow">${styles[style]}</span><h2>${esc(text(name))}</h2><p>流程需求樓層 ${q.needFloor}。需配合對應流派與武器條件。</p><ol>${q.steps.map(s=>'<li>'+goalText(s.goal)+'</li>').join('')}</ol><p class="subtle">完整對話、解鎖條件與最終效果待確認。</p></article>`;}).join('')}</div>`;}

const BUILD_KEY='sao-guide-build-current-v1';
function freshBuild(){return{level:70,style:'sword',mastery:1,unique:false,dualWield:false,slots:{},talents:{},buffs:[],extra:{}};}
function cleanBuild(value){const b=freshBuild();if(!value||typeof value!=='object')return b;b.level=Math.max(1,Math.min(120,Math.floor(+value.level||1)));b.style=styles[value.style]?value.style:'sword';b.mastery=Math.max(1,Math.min(10,Math.floor(+value.mastery||1)));b.unique=!!value.unique;b.dualWield=!!value.dualWield;
 for(const slot of G.slotKeys){const g=value.slots?.[slot],item=items.get(g?.id);if(!item||!allowedSlot(item,slot,b.style))continue;const enh={};let remaining=G.maxEnhance(item);for(const k of G.enhanceDirections(item)){enh[k]=Math.max(0,Math.min(remaining,Math.floor(+g.enh?.[k]||0)));remaining-=enh[k];}const out={id:item.id,enh,preset:['balanced','custom',...G.enhanceDirections(item)].includes(g.preset)?g.preset:'balanced'};if(g.bonus&&typeof g.bonus==='object'){out.bonus={};for(const [k,v]of Object.entries(g.bonus))if((statMap.has(k)||k==='maxHp')&&Number.isFinite(v)&&Math.abs(v)<=1e7)out.bonus[k]=v;}b.slots[slot]=out;}
 for(const n of D.talentNodes.filter(n=>n.style===b.style)){const v=value.talents?.[n.id];if(Number.isFinite(v)&&v>0)b.talents[n.id]=Math.min(n.max,Math.floor(v));}
 for(const s of D.skills)if(b.talents['br:'+s.id+':a']&&b.talents['br:'+s.id+':b'])delete b.talents['br:'+s.id+':b'];
 // A shared/imported tree must obey the same path, rank, tier and point constraints as an interactive tree.
 let p=G.createPlayer(b);if(G.validateTree(p,b.style,b.talents)||Object.values(b.talents).reduce((a,v)=>a+v,0)>G.calculate(b).talentPoints||D.talentNodes.some(n=>n.style===b.style&&b.talents[n.id]&&!G.talentTierAllowed(p,b.style,n.tier)))b.talents={};
 b.buffs=D.buffs.filter(x=>(value.buffs||[]).includes(x.id)&&(x.party||x.style===b.style)&&b.level>=x.reqLevel).map(x=>x.id);
 for(const [k,v]of Object.entries(value.extra||{}))if((statMap.has(k)||k==='maxHp')&&Number.isFinite(v)&&Math.abs(v)<=1e7)b.extra[k]=v;
 if(G.weaponTwoHanded(items.get(b.slots.weapon?.id)?.weaponType||'',G.createPlayer(b)))delete b.slots.offhand;
 return b;
}
function allowedSlot(item,slot,style){if(slot==='weapon')return item.slot==='weapon'&&item.weaponType===(style==='holy'?'sword':style);if(slot==='offhand')return item.slot==='offhand'||item.slot==='weapon'&&['sword','dagger'].includes(item.weaponType)&&item.weaponType===(style==='holy'?'sword':style);return item.slot===({ear2:'ear',ring2:'accessory'}[slot]||slot);}
function encodeBuild(b){const bytes=new TextEncoder().encode(JSON.stringify(cleanBuild(b)));let s='';for(const c of bytes)s+=String.fromCharCode(c);return'3.'+btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decodeBuild(s){if(typeof s!=='string'||s.length>30000)throw Error('配裝連結過長或無效');if(s.startsWith('3.')){if(!/^[A-Za-z0-9_-]+$/.test(s.slice(2)))throw Error('配裝連結格式不正確');return cleanBuild(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(s.slice(2).replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0)))));}const legacy=window.BuildGuide.decodeShare(s,equipment.map(x=>({...x,name:named(x),quality:quality[G.quality(x)]})));const out=freshBuild();out.level=legacy.level;out.style=items.get(legacy.slots.weapon?.id)?.weaponType||'sword';out.slots=legacy.slots;return cleanBuild(out);}
function buildPage(params){let b=freshBuild(),message='';try{if(params.get('b')){b=decodeBuild(params.get('b'));if(!params.get('b').startsWith('3.'))message='已轉換舊版配裝連結。舊版增益、獨特技能與強化設定需要依新版重新選擇。';}else{const raw=localStorage.getItem(BUILD_KEY);if(raw)b=cleanBuild(JSON.parse(raw));}}catch(e){message='配裝設定無法讀取：'+e.message;}
 const added=items.get(params.get('item'));if(added?.kind==='equipment'){if(added.weaponType)b.style=added.weaponType;if(allowedSlot(added,added.slot,b.style))b.slots[added.slot]={id:added.id,enh:{}};b=cleanBuild(b);}
 main.innerHTML=intro('配裝模擬器','用新版裝備與天賦規劃定位，並保留你的配裝設定。')+note('這裡計算<strong>角色常駐能力與普攻間隔</strong>。裝備基底是參考模板；隨機詞條請改為輸入實物性能。未取得的套裝與獨特技能動態效果不計入，無法作為完整實戰 DPS。')+`<div id="build-message" role="status">${esc(message)}</div><section class="panel v2-build-controls"><div class="v2-filters">${field('角色等級','<input id="b-level" type="number" min="1" max="120" value="'+b.level+'">')}${field('流派',select('b-style',Object.entries(styles).map(([k,v])=>option(k,v,b.style===k)).join('')))}${field('技能熟練等級',select('b-mastery',Array.from({length:10},(_,i)=>option(i+1,'Lv'+(i+1),b.mastery===i+1)).join('')))}${field('推薦定位',select('b-role',option('tank','坦克')+option('support','輔助')+option('damage','輸出')))}</div><div class="v2-actions"><button class="button" id="b-recommend">推薦配裝</button><button class="button secondary" id="b-share">複製分享連結</button><button class="button secondary" id="b-export">下載配裝</button><label class="button secondary">匯入配裝<input class="sr-only" id="b-import" type="file" accept=".json,application/json"></label><button class="button secondary" id="b-clear">清空配裝</button></div><p class="section-note">推薦使用需求等級內、已確認商店有售的基底裝備，依定位比較性能；不假設隨機詞條或套裝加成。</p></section><div id="build-summary" class="v2-build-summary" aria-live="polite"></div><div class="v2-tabs"><button data-btab="gear" class="button secondary active">裝備與性能</button><button data-btab="talents" class="button secondary">天賦投點</button><button data-btab="buffs" class="button secondary">增益與額外能力</button></div><div id="b-gear"></div><div id="b-talents" hidden></div><div id="b-buffs" hidden></div>`;
 const save=()=>{try{localStorage.setItem(BUILD_KEY,JSON.stringify(b));history.replaceState(null,'',location.pathname+location.search+'#build?b='+encodeBuild(b));}catch{};};const status=s=>$('build-message').textContent=s;
 function summary(){const r=G.calculate(b),s=r.stats;const warnings=[];if(!r.activeStyle)warnings.push('主手或副手不符合所選流派，天賦未生效。');if(b.slots.offhand&&items.get(b.slots.offhand.id)?.slot==='weapon'&&!b.dualWield&&b.style==='sword')warnings.push('雙劍需要二刀流解鎖，請確認遊戲中的解鎖狀態。');for(const g of Object.values(b.slots)){const x=items.get(g.id);if((x.reqLevel||1)>b.level)warnings.push(named(x)+' 超過角色需求等級。');}if(Object.values(b.slots).some(g=>items.get(g.id)?.set))warnings.push('已裝備套裝；套裝加成尚未計入。');$('build-summary').innerHTML=`<div class="v2-metrics">${[['HP',nf(s.maxHp)],['主手攻擊',nf(s.atk)],['防禦',nf(s.def)],['普攻間隔',nf(r.interval/1000)+' 秒'],['攻速顯示',nf(r.attackSpeed)],['暴擊率',pct(s.crit)],['額外暴擊傷害',pct(s.critDmg||0)],['敏捷',nf(s.agi)]].map(([k,v])=>`<div class="panel"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><details class="panel"><summary>完整常駐能力</summary><div class="v2-statline">${statSummary(s)}</div><p>基本暴擊傷害倍率為 160%，加上面板的額外暴擊傷害。抗性、減傷及穿透還有上限與樓層修正，請見${a('systems',null,'戰鬥規則')}。</p></details>${warnings.length?note(warnings.map(esc).join('<br>')):''}`;save();}
 function gearCards(){const opened=new Set(Array.from($('b-gear').querySelectorAll('[data-slot] details[open]'),x=>x.closest('[data-slot]').dataset.slot));const two=G.weaponTwoHanded(items.get(b.slots.weapon?.id)?.weaponType||'',G.createPlayer(b));$('b-gear').innerHTML=`<div class="v2-geargrid">${G.slotKeys.map(slot=>{const g=b.slots[slot],x=items.get(g?.id),disabled=slot==='offhand'&&two;return`<section class="panel v2-gearcard" data-slot="${slot}"><h2>${slots[slot]}</h2>${disabled?'<p>目前主手為雙手武器，副手不生效。</p>':`<label class="field">搜尋裝備<input data-gear-search type="search" placeholder="搜尋${slots[slot]}裝備…"></label><label class="field">選擇裝備<select data-gear-select>${gearOptions(slot,'',g?.id)}</select></label>${x?`<p>${tag('需求 Lv'+(x.reqLevel||1))} ${tag(quality[G.quality(x)])}${x.set?' '+tag('套裝 '+x.set):''}</p><p class="section-note">${esc(sourceShort(x.id))}</p>${window.SAOClassicLayout.gearControls(g,x)}<div class="v2-statline">${gearDiff(x,g)}</div><details><summary>強化與實際性能</summary><p class="section-note">基底參考可分配舊式強化；帶隨機詞條的實物，請輸入<strong>已含強化的最終性能</strong>，避免重複計算。</p>${!x.shop?`<div class="v2-enh">${G.enhanceDirections(x).map(k=>field(window.BuildGuide.directionsInfo[k]?.[0]||k,`<input data-enh="${k}" type="number" min="0" max="${G.maxEnhance(x)}" value="${g.enh?.[k]||0}" ${g.bonus?'disabled':''}>`)).join('')}</div><p class="section-note">參考上限 +${G.maxEnhance(x)}；實際強化限制以遊戲為準。</p>`:'<p class="section-note">商店基底不提供強化分配。</p>'}<label class="check-field"><input data-manual type="checkbox" ${g.bonus?'checked':''}> 輸入實物最終性能（取代基底）</label>${g.bonus?`<div class="v2-manualstats">${editableStats.map(k=>field(statName(k)+(rate(k)?' %':''),`<input data-bonus="${k}" type="number" step="any" value="${g.bonus[k]===undefined?'':rate(k)?nfInput(g.bonus[k]*100):g.bonus[k]}" placeholder="0">`)).join('')}</div>`:''}</details>`:'<p class="subtle">尚未選擇裝備</p>'}`}</section>`;}).join('')}</div>`;
 for(const slot of opened)$('b-gear').querySelector('[data-slot="'+slot+'"] details')?.setAttribute('open','');
 for(const card of $('b-gear').querySelectorAll('[data-slot]')){const slot=card.dataset.slot;card.querySelector('[data-gear-search]')?.addEventListener('input',e=>{const target=card.querySelector('[data-gear-select]');target.innerHTML=gearOptions(slot,e.target.value,b.slots[slot]?.id);});card.querySelector('[data-gear-select]')?.addEventListener('change',e=>{if(e.target.value)b.slots[slot]={id:e.target.value,enh:{}};else delete b.slots[slot];b=cleanBuild(b);gearCards();summary();});for(const control of card.querySelectorAll('[data-classic-plus],[data-classic-preset]'))control.onchange=()=>{const g=b.slots[slot],x=items.get(g.id),dirs=G.enhanceDirections(x),total=Number(card.querySelector('[data-classic-plus]').value),preset=card.querySelector('[data-classic-preset]').value;g.preset=preset;if(preset==='balanced')g.enh=Object.fromEntries(dirs.map((k,i)=>[k,Math.floor(total/dirs.length)+(i<total%dirs.length?1:0)]));else if(dirs.includes(preset))g.enh=Object.fromEntries(dirs.map(k=>[k,k===preset?total:0]));else{let left=total;for(const k of dirs){g.enh[k]=Math.min(left,g.enh[k]||0);left-=g.enh[k];}g.enh[dirs[0]]=(g.enh[dirs[0]]||0)+left;}b=cleanBuild(b);gearCards();summary();};for(const input of card.querySelectorAll('[data-enh]'))input.addEventListener('change',()=>{const g=b.slots[slot];g.enh[input.dataset.enh]=Number(input.value);b=cleanBuild(b);gearCards();summary();});card.querySelector('[data-manual]')?.addEventListener('change',e=>{const g=b.slots[slot];if(e.target.checked)g.bonus={...G.gear(items.get(g.id),g).bonus};else delete g.bonus;gearCards();summary();});for(const input of card.querySelectorAll('[data-bonus]'))input.addEventListener('change',()=>{const k=input.dataset.bonus,g=b.slots[slot];g.bonus[k]=Number(input.value)/(rate(k)?100:1);b=cleanBuild(b);summary();card.querySelector('.v2-statline').innerHTML=gearDiff(items.get(g.id),g);});}
 }
 function gearOptions(slot,q,id){return option('','不裝備')+equipment.filter(x=>allowedSlot(x,slot,b.style)&&(!q||(named(x)+' '+x.id).toLowerCase().includes(q.toLowerCase())||x.id===id)).sort((a,c)=>(a.reqLevel||1)-(c.reqLevel||1)).map(x=>option(x.id,named(x)+' · Lv'+(x.reqLevel||1),x.id===id)).join('');}
 function gearDiff(x,g){const item=G.gear(x,g),fin=item.bonus||{},base=x.bonus||{};const rows=Object.entries(fin).filter(([,v])=>v!==0).map(([k,v])=>{if(g.bonus)return `<span>${esc(statName(k))} <b class="v2-base">${v>0?'+':''}${val(k,v)}</b></span>`;const initial=base[k]||0,extra=v-initial;return `<span>${esc(statName(k))} <b class="v2-base">${initial>0?'+':''}${val(k,initial)}</b>${Math.abs(extra)>1e-9?` <b class="v2-plus">+ ${val(k,extra)}</b>`:''}</span>`;});if(x.weaponType){const raw=x.speed||100,final=item.speed||raw;rows.push(`<span>${esc(statName('speed'))} <b class="v2-base">${nf(raw)}</b>${final!==raw?` <b class="v2-plus">+ ${nf(final-raw)}</b>`:''}</span>`);}return (g.bonus?'<span class="v2-manual-label">&#23526;&#29289;&#26368;&#32066;&#24615;&#33021;</span>':'')+rows.join(' ')||'—';}

 function talents(){const r=G.calculate(b),nodes=D.talentNodes.filter(n=>n.style===b.style);$('b-talents').innerHTML=`<section class="panel"><div class="v2-actions"><h2>可用 ${r.talentPoints-r.spent}／${r.talentPoints} 點</h2><button class="button secondary" id="b-reset-talents">重置天賦</button></div><p>沿已連接路徑投點，技能分支只能擇一。未公開的終階效果保留為待確認。</p><label class="check-field"><input id="b-unique" type="checkbox" ${b.unique?'checked':''}> 已解鎖此流派獨特技能（動態效果未計入）</label>${b.style==='sword'?`<label class="check-field"><input id="b-dual" type="checkbox" ${b.dualWield?'checked':''}> 已解鎖二刀流，可使用副手劍</label>`:''}</section>${Array.from({length:8},(_,tier)=>{const list=nodes.filter(n=>n.tier===tier);return list.length?`<details class="panel" open><summary>第 ${tier+1} 階 · 前置 ${D.talentCosts[tier]} 點</summary><div class="v2-nodegrid">${list.map(n=>{const rank=G.talentRank(r.player,n);return`<div class="v2-node ${rank?'allocated':''}"><strong>${esc(nodeLabel(n))}</strong><small>${esc(nodeDesc(n))}</small><div class="v2-node-controls"><button class="button secondary" data-node="${esc(n.id)}" data-delta="-1" aria-label="減少${esc(nodeLabel(n))}" ${!b.talents[n.id]?'disabled':''}>−</button><span>${rank} / ${n.max}</span><button class="button secondary" data-node="${esc(n.id)}" data-delta="1" aria-label="增加${esc(nodeLabel(n))}" ${rank>=n.max?'disabled':''}>＋</button></div></div>`;}).join('')}</div></details>`:'';}).join('')}`;
 $('b-reset-talents').onclick=()=>{b.talents={};talents();summary();};$('b-unique').onchange=e=>{b.unique=e.target.checked;talents();summary();};if($('b-dual'))$('b-dual').onchange=e=>{b.dualWield=e.target.checked;summary();};for(const button of $('b-talents').querySelectorAll('[data-node]'))button.onclick=()=>{const id=button.dataset.node,n=D.talentNodes.find(n=>n.id===id),next={...b.talents},delta=+button.dataset.delta;next[id]=(next[id]||0)+delta;if(next[id]<=0)delete next[id];const p=G.createPlayer({...b,talents:next}),spent=Object.values(next).reduce((a,v)=>a+v,0);if(delta>0&&spent>r.talentPoints)return status('天賦點數不足。');if(delta>0&&!G.talentTierAllowed(r.player,b.style,n.tier))return status('尚未達到此階的前置投入點數。');if(n.kind==='branch'&&delta>0&&next[`br:${n.skill}:${n.branch.path==='a'?'b':'a'}`])return status('同一技能的兩條分支只能選一條。');const bad=G.validateTree(p,b.style,next);if(bad)return status('需要先滿足連接與前置條件：'+nodeLabel(bad));b.talents=next;status('已更新天賦。');talents();summary();};
 }
 function buffs(){ $('b-buffs').innerHTML=`<section class="panel"><h2>已套用增益</h2><p>可選自身流派增益及隊友提供的隊伍增益；此處視為持續生效，不計覆蓋率。</p><div class="v2-checkgrid">${D.buffs.filter(x=>(x.party||x.style===b.style)&&x.reqLevel<=b.level).map(x=>`<label class="check-field"><input data-buff="${x.id}" type="checkbox" ${b.buffs.includes(x.id)?'checked':''}> ${esc(named(x))} · ${styles[x.style]}${x.party?'（隊伍）':''}<small>${Object.entries(x.effect).map(([k,v])=>esc(statName(k))+' '+pct(v)).join(' · ')}</small></label>`).join('')}</div></section><section class="panel"><h2>額外常駐能力</h2><p>如稱號或已確認的套裝常駐加成，可在這裡輸入。不會自動推測動態效果。</p><div class="v2-manualstats">${editableStats.map(k=>field(statName(k)+(rate(k)?' %':''),`<input data-extra="${k}" type="number" step="any" value="${b.extra[k]===undefined?'':rate(k)?nfInput(b.extra[k]*100):b.extra[k]}" placeholder="0">`)).join('')}</div></section>`;for(const input of $('b-buffs').querySelectorAll('[data-buff]'))input.onchange=()=>{b.buffs=Array.from($('b-buffs').querySelectorAll('[data-buff]:checked'),i=>i.dataset.buff);summary();};for(const input of $('b-buffs').querySelectorAll('[data-extra]'))input.onchange=()=>{const k=input.dataset.extra;b.extra[k]=Number(input.value)/(rate(k)?100:1);b=cleanBuild(b);summary();};}
 for(const button of main.querySelectorAll('[data-btab]'))button.onclick=()=>{for(const name of ['gear','talents','buffs'])$('b-'+name).hidden=name!==button.dataset.btab;main.querySelectorAll('[data-btab]').forEach(x=>x.classList.toggle('active',x===button));if(button.dataset.btab==='talents')talents();if(button.dataset.btab==='buffs')buffs();};
 $('b-level').onchange=e=>{b.level=Number(e.target.value);b=cleanBuild(b);e.target.value=b.level;gearCards();talents();buffs();summary();};$('b-style').onchange=e=>{b.style=e.target.value;b.talents={};b=cleanBuild(b);gearCards();talents();buffs();summary();};$('b-mastery').onchange=e=>{b.mastery=Number(e.target.value);summary();};
 $('b-recommend').onclick=()=>{const role=$('b-role').value;const weights=role==='tank'?{maxHp:.15,def:2,block:2000,dmgTaken:5000,con:8,hpPct:1000}:role==='support'?{def:1,maxHp:.08,cdr:4000,agi:12,con:4,speedPct:700}:{atk:2,str:15,crit:2000,critDmg:600,speedPct:1800,agi:8};for(const slot of G.slotKeys){let list=equipment.filter(x=>allowedSlot(x,slot,b.style)&&(x.reqLevel||1)<=b.level&&(sources.get(x.id)||[]).some(s=>s.kind==='shop'));if(slot==='offhand'){if(G.weaponTwoHanded(items.get(b.slots.weapon?.id)?.weaponType||'',G.createPlayer(b))){delete b.slots[slot];continue;}list=list.filter(x=>x.shield||b.style==='dagger'||b.dualWield&&b.style==='sword');}const score=x=>Object.entries(weights).reduce((s,[k,w])=>s+(x.bonus?.[k]||0)*w,0);list.sort((a,c)=>score(c)-score(a)||(c.reqLevel||1)-(a.reqLevel||1));if(list[0])b.slots[slot]={id:list[0].id,enh:{}};else delete b.slots[slot];}b=cleanBuild(b);gearCards();summary();status('已依'+({tank:'坦克',support:'輔助',damage:'輸出'}[role])+'定位選擇有售基底；實際詞條與套裝請再比較。');};
 $('b-share').onclick=async()=>{const url=location.origin+location.pathname+'#build?b='+encodeBuild(b);try{await navigator.clipboard.writeText(url);status('已複製分享連結。');}catch{detail('分享配裝',field('複製連結',`<textarea readonly rows="5">${esc(url)}</textarea>`));}};$('b-export').onclick=()=>download('SAO配裝.json',b);$('b-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('檔案過大');b=cleanBuild(JSON.parse(await file.text()));save();buildPage(new URLSearchParams());}catch(err){status('匯入失敗：'+err.message);}};$('b-clear').onclick=()=>{b=freshBuild();save();buildPage(new URLSearchParams());};gearCards();talents();buffs();summary();
}
function nfInput(n){return Math.round(n*1e8)/1e8;}
function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function experiencePage(){main.innerHTML=intro('升級經驗','查詢各角色等級升到下一級所需經驗，並用實際收益推算時間。')+`<section class="panel"><div class="v2-filters">${field('目前等級','<input id="xp-level" type="number" min="1" max="119" value="70">')}${field('目前等級內經驗','<input id="xp-now" type="number" min="0" value="0">')}${field('每分鐘經驗','<input id="xp-rate" type="number" min="0" value="0">')}${field('目標等級','<input id="xp-target" type="number" min="2" max="120" value="75">')}</div><div id="xp-summary" aria-live="polite"></div></section><details class="panel"><summary>完整計算公式</summary><p>升級需求 = 四捨五入 { max[0.006 × 等級<sup>1.5</sup> × (1 + (等級 ÷ 50)²), 低等級修正] × 370 × 四捨五入[10 × 1.2<sup>等級−1</sup>] × 進程倍率 }。</p><p>Lv1–5：前段成長值 ×3；Lv6 以上：至少保留 Lv5 的三倍成長值。進程倍率 = 1 + 0.7 × min[1, max(0, (等級−10) ÷25)]。</p></details><section class="panel"><div class="v2-filters">${field('顯示至等級',select('xp-cap',option(75,'Lv1–75')+option(120,'Lv1–120')))}</div><div id="xp-table"></div></section>`;
 function draw(){const lv=Math.min(119,Math.max(1,Math.floor(+$('xp-level').value||1))),now=Math.max(0,+$('xp-now').value||0),rate=Math.max(0,+$('xp-rate').value||0),target=Math.max(lv+1,Math.min(120,Math.floor(+$('xp-target').value||lv+1)));let total=0;for(let l=lv;l<target;l++)total+=G.experience(l);total=Math.max(0,total-now);const next=Math.max(0,G.experience(lv)-now);$('xp-summary').innerHTML=`<div class="v2-metrics">${[['下一級剩餘',nf(next)],['每小時經驗',nf(rate*60)],['每天經驗',nf(rate*1440)],['至 Lv'+target,nf(total)],['下一級時間',rate?duration(next/rate*60):'請輸入收益'],['目標等級時間',rate?duration(total/rate*60):'請輸入收益']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="section-note">收益按固定效率外推，未預測升級後折減或換區域；Lv120 為等級上限。</p>`;}
 for(const id of ['xp-level','xp-now','xp-rate','xp-target'])$(id).oninput=draw;function rows(){const cap=+$('xp-cap').value;$('xp-table').innerHTML=table(['目前等級','下一級','本級升級所需','從 Lv1 累計所需'],Array.from({length:cap},(_,i)=>i+1).map(l=>`<tr><td>Lv${l}</td><td>${l===120?'等級上限':'Lv'+(l+1)}</td><td>${l===120?'—':nf(G.experience(l))}</td><td>${nf(G.totalExperience(l,0))}</td></tr>`).join(''));} $('xp-cap').onchange=rows;draw();rows();}
function duration(s){if(!Number.isFinite(s))return'—';if(s<60)return nf(Math.ceil(s))+' 秒';if(s<3600)return nf(s/60)+' 分鐘';if(s<86400)return nf(s/3600)+' 小時';return nf(s/86400)+' 天';}
function speedPage(){main.innerHTML=intro('攻速、敏捷與普攻間隔','新版不再沿用舊版的攻速 500 目標與敏捷公式。')+`<section class="panel"><div class="v2-filters">${field('武器基礎攻速','<input id="sp-weapon" type="number" min="1" max="1000" value="100">')}${field('敏捷','<input id="sp-agi" type="number" min="-1000" max="10000" value="0">')}${field('攻速加成 %','<input id="sp-bonus" type="number" min="-90" max="10000" value="0">')}</div><div id="sp-result"></div></section><section class="panel"><h2>完整公式</h2><p>攻速加成原值 x = 裝備與天賦攻速加成 + 0.006 × 敏捷。</p><p>正加成軟上限 f(x) = x ÷ (1 + x ÷ 3)；負加成最低為 −90%。</p><p>有效 speed = (武器攻速 ÷ 100) × [1 + f(x)]。</p><p>普攻間隔 = max[100 毫秒, 四捨五入(2000 ÷ 有效 speed)]。</p><p>攻速面板 = 四捨五入(200000 ÷ 普攻間隔)。雙持使用兩把武器的基礎攻速平均值；其他攻速增益先依角色公式合併，再套軟上限。</p></section>`;function draw(){const weapon=Math.max(1,+$('sp-weapon').value||1),agi=+$('sp-agi').value||0,bonus=(+$('sp-bonus').value||0)/100,speed=weapon/100*(1+G.softSpeed(bonus+.006*agi)),interval=G.interval({speed});$('sp-result').innerHTML=`<div class="v2-metrics">${[['普攻間隔',nf(interval)+' 毫秒'],['攻速面板',nf(G.attackSpeed(interval))],['每分鐘普攻次數',nf(60000/interval)],['有效 speed',nf(speed)]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>`;}for(const e of main.querySelectorAll('input'))e.oninput=draw;draw();}
function systemsPage(){main.innerHTML=intro('新系統指南','先掌握新版常駐規則，再比較配裝與實戰表現。')+`<div class="v2-cards">${[['裝備欄位','主手、副手、頭部、身體、手套、鞋子、項鍊、兩個耳環、兩個戒指與披風，共 12 欄。'],['八種流派','單手劍、細劍、太刀、雙手斧、單手槌、劍盾、鐮刀與短刀。劍盾使用單手劍；部分招式必須持盾。'],['隨機詞條','相同名稱的裝備，物品等級與詞條可能不同。比較時請看實物最終性能，不能只依圖鑑基底排名。'],['套裝','同套裝部件可互相搭配。圖鑑提供部件索引；未取得的套裝觸發條件與加成數值暫不推測。'],['天賦與分支','每升一級取得一點基本天賦點。技能、增益、特色天賦、常駐能力與額外技能欄位由天賦樹連接。'],['公會、倉庫與交易','新增公會、倉庫、拍賣及市場相關介面。價格、交易限制、開放條件與伺服器即時資訊請以遊戲為準。']].map(([t,d])=>`<section class="panel"><h2>${t}</h2><p>${d}</p></section>`).join('')}</div><section class="panel"><h2>力量、敏捷、體質</h2>${table(['屬性','每點常駐效果'],[['力量','基本攻擊 +0.2%、基本防禦 +0.4%'],['敏捷','迴避 +0.1%，攻速加成原值 +0.6%；迴避與攻速另外套軟上限'],['體質','基本 HP +0.4%、異常抗性 +0.2%']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join(''))}<p class="section-note">「基本」指角色等級所提供的基礎值，並非把整套裝備性能再按屬性直接乘算。</p></section><section class="panel"><h2>防禦與抗性</h2><p>傷害新增斬擊、突刺、打擊及對應抗性；全抗性會合併進一般傷害抗性。暴擊基本倍率為 160%。</p>${table(['項目','基本上限'],Object.entries(D.statCaps).map(([k,v])=>`<tr><td>${esc(statName(k))}</td><td>${pct(v)}</td></tr>`).join(''))}<p>抗性有樓層壓力：每超過 10 層，額外扣除 10%，最多扣除 90%。特殊效果可調整抗性上限；實際戰鬥還會受敵方穿透影響。</p><p>迴避在 28% 以上開始遞減：有效迴避 = 28% + 32% × tanh[(原始迴避−28%) ÷32%]，上限漸近 60%。</p></section><section class="panel"><h2>仍待補全的資料</h2><p>怪物完整能力與獎勵、掉落表、部分新區域與裝備名稱、隨機詞條範圍、套裝加成、獨特技能動態倍率，以及地下迷宮新版事件與評分規則。</p><p>舊版的 Lv63 經驗折減、攻略進度折減與迷宮選詞條結論不會直接套入新版。取得新版實測後才恢復收益試算與路線評分。</p></section>`;}
function aboutPage(){main.innerHTML=intro('使用說明','玩家整理的 Snored Art Online 攻略資料庫。')+`<section class="panel"><h2>查詢與計算範圍</h2><p>本站提供區域配置、裝備基底、技能、天賦、任務和常駐能力試算。這些內容不是即時同步，可能與遊戲實物或伺服器調整不同。</p><p>「待確認」代表尚未取得新版實際資料，並非沒有能力、沒有掉落或數值為零。圖鑑提供 1–75 層配置，開放進度以遊戲為準。</p><h2>配裝保存</h2><p>模擬器設定只儲存在目前瀏覽器。可以下載 JSON 或複製分享連結備份；清除瀏覽器網站資料會移除本機保存。</p><h2>回報資料</h2><p>回報怪物掉落、技能或收益時，請附角色等級、最高已通關樓層、分配人數、怪物名稱與遊戲實際紀錄。裝備請附物品等級、詞條與強化後性能。</p></section>`;}
function accountPage(){main.innerHTML=intro('帳號查詢','查詢角色快照，或匯入自己的角色 JSON。')+`<section class="panel"><h2>登入查詢</h2><p><strong>查詢會重新登入並中斷原本的遊戲連線。</strong>查完後請回遊戲重新登入。</p><form id="account-form"><div class="v2-filters">${field('遊戲帳號','<input id="account-name" autocomplete="off" required>')}${field('遊戲密碼','<input id="account-pass" type="password" autocomplete="off" required>')}</div><label class="check-field"><input id="account-ack" type="checkbox" required> 我了解查詢會中斷遊戲登入</label><button class="button" type="submit">登入並查詢</button></form><p class="section-note">帳密經本站 Cloudflare 查詢服務傳給遊戲，不儲存在本站；結果只暫留目前分頁。只查詢自己的帳號。</p><p id="account-status" role="status"></p></section><section class="panel"><h2>匯入角色資料</h2><p>檔案僅在目前瀏覽器解析，不會上傳。支援包含 player 的角色快照。</p><input id="account-import" type="file" accept=".json,application/json"></section><div id="account-result"></div>`;
 function show(d){const p=d.player??d.state?.player;if(!p){$('account-result').innerHTML=empty('檔案沒有可讀取的角色資料');return;}$('account-result').innerHTML=`<section class="panel"><h2>${esc(p.name||'角色')} · Lv${esc(p.level)}</h2><p>HP ${nf(p.hp||0)} · 本級經驗 ${nf(p.exp||0)}／${nf(G.experience(p.level||1))} · 摳 ${nf(p.col||0)}</p><p>目前位置 ${a('floors',p.areaId,areaName(p.areaId))} · 最高已通關 ${Math.max(0,...(p.clearedFloors||[]))} 層</p></section><section class="panel"><h2>裝備快照</h2>${table(['部位','裝備','實際性能'],G.slotKeys.map(slot=>{const id=p.equipment?.[slot];if(!id)return'';let item;try{item=G.nativeGear(p,id);}catch{}return`<tr><td>${slots[slot]}</td><td>${item?a('equipment',item.id,named(item)):esc(id)}</td><td>${item?statSummary(item.bonus)+(id.startsWith('g:')&&!p.gear?.[id.slice(2)]?.ax?'<small class="v2-sub">&#22522;&#24213;&#21443;&#32771;&#65307;&#23578;&#26410;&#25552;&#20379;&#26032;&#29256;&#35422;&#26781;</small>':''):'物品資料尚未取得'}</td></tr>`;}).join(''))}</section>`;}
 $('account-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20e6)throw Error('檔案過大');show(JSON.parse(await f.text()));}catch(err){$('account-status').textContent='讀取失敗：'+err.message;}};$('account-form').onsubmit=async e=>{e.preventDefault();if(!e.target.reportValidity())return;const button=e.target.querySelector('button'),account=$('account-name').value.trim(),password=$('account-pass').value;button.disabled=true;$('account-pass').value='';$('account-status').textContent='查詢中…';try{const r=await fetch('https://sao-account-query.chengyen1209.workers.dev/query',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(50000),body:JSON.stringify({account,password,acknowledged:true})});const data=await r.json();if(!r.ok)throw Error(data.error||'查詢失敗');show(data);$('account-status').textContent='查詢完成，連線已關閉。請回遊戲重新登入。';}catch(err){$('account-status').textContent='查詢失敗：'+err.message;}finally{button.disabled=false;$('account-ack').checked=false;}};
}

