function closeMenu(){$('sidebar').classList.remove('open');$('sidebar-backdrop').hidden=true;$('menu-toggle').setAttribute('aria-expanded','false');syncMenu();}
function syncMenu(){$('sidebar').inert=matchMedia('(max-width:760px)').matches&&!$('sidebar').classList.contains('open');}
function route(){const [raw,query]=(location.hash.slice(1)||'home').split('?'),page=pages[raw]?raw:'home',params=new URLSearchParams(query||'');document.title=pages[page][0]+'｜SAO 攻略資料庫';$('breadcrumb').textContent=pages[page][0];document.querySelectorAll('[data-page]').forEach(x=>{x.classList.toggle('active',x.dataset.page===page);if(x.dataset.page===page)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});for(const dialog of document.querySelectorAll('dialog[open]'))dialog.close();closeMenu();try{pages[page][1](params);window.SAOClassicLayout.apply(main,page);}catch(err){console.error(err);main.innerHTML=intro('無法顯示資料','這份配裝或資料格式無法解析。')+empty(err.message)+'<a class="button" href="#home">回首頁</a>';}window.scrollTo(0,0);}
const searchIndex=[...window.SAO_ACHIEVEMENTS.entries.filter(x=>!x.hidden).map(x=>({name:x.name,sub:x.desc+' '+(x.titleName||''),page:'achievements',id:x.id})),...equipment.map(x=>({name:named(x),sub:`${slots[x.slot]} · Lv${x.reqLevel||1}`,page:'equipment',id:x.id})),...D.monsters.map(x=>({name:named(x),sub:monsterKinds[monsterKind(x)],page:'monsters',id:x.id})),...D.areas.map(x=>({name:named(x),sub:`第 ${x.floor} 層`,page:'floors',id:x.id})),...D.skills.concat(D.buffs).map(x=>({name:named(x),sub:styles[x.style],page:'skills',id:x.id,style:x.style})),...D.talents.map(x=>({name:named(x),sub:styles[x.style]+' 天賦',page:'talents',id:x.id})),...D.chapters.map(x=>({name:titleChapter(x),sub:'章節流程',page:'quests',id:x.id})),...Object.entries(pages).map(([id,[name]])=>({name,sub:'攻略頁面',page:id}))];
function search(){const q=$('global-search').value.trim().toLowerCase(),hits=q?searchIndex.filter(x=>(x.name+' '+x.sub+' '+(x.id||'')).toLowerCase().includes(q)).sort((a,b)=>(b.name.toLowerCase()===q)-(a.name.toLowerCase()===q)):[];$('global-results').innerHTML=q?(hits.length?`<p class="subtle">找到 ${nf(hits.length)} 筆，顯示前 40 筆</p>`+hits.slice(0,40).map(x=>`<a class="search-hit" href="${href(x.page,x.id)+(x.style?'&style='+x.style:'')}"><span class="hit-main">${esc(x.name)}<small>${esc(x.sub)}</small></span><span class="hit-category">查看 →</span></a>`).join(''):empty()):'<p class="section-note">搜尋裝備、怪物、區域、技能、天賦或章節。</p>';}
