for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.dialog-close,.detail-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog||e.target.closest('a[href^="#"]'))dialog.close();});}
 $('search-trigger').onclick=openSearch;$('global-search').oninput=search;document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();openSearch();}});$('menu-toggle').onclick=()=>{const open=!$('sidebar').classList.contains('open');$('sidebar').classList.toggle('open',open);$('sidebar-backdrop').hidden=!open;$('menu-toggle').setAttribute('aria-expanded',String(open));syncMenu();};$('sidebar-backdrop').onclick=closeMenu;matchMedia('(max-width:760px)').addEventListener('change',syncMenu);
